"""Build PIT weekly state scores for every supported SW2021 L1 industry."""
from __future__ import annotations
import argparse,json
from pathlib import Path
import numpy as np,pandas as pd
from experiments.run_analyst_revision import consensus_revisions,load_reports
from experiments.weekly_industry_cycle import mark_entry_events,score_weekly_states,weekly_last_sessions
from factormine.config import Config
from factormine.data.db import connect
from factormine.data.panel import load_or_build_panel
from factormine.research.combination import repair_point_in_time_size
UNSUPPORTED={"银行","非银金融"}
def statement(path,fields):
 d=pd.read_csv(path,dtype={"ts_code":str,"ann_date":str,"f_ann_date":str,"end_date":str});d["Symbol"]=d.ts_code.str[:6];d["ann_date"]=pd.to_datetime(d.ann_date,errors="coerce");d["f_ann_date"]=pd.to_datetime(d.f_ann_date,errors="coerce") if "f_ann_date" in d else pd.NaT;d["visible"]=d.f_ann_date.fillna(d.ann_date);d["end_date"]=pd.to_datetime(d.end_date,errors="coerce");d["update_flag"]=pd.to_numeric(d.update_flag,errors="coerce").fillna(0);return d[["Symbol","end_date","visible","update_flag",*fields]].dropna(subset=["end_date","visible"]).drop_duplicates()
def financial_snapshot(con,day):
 return con.execute("""with f as (select * exclude(rn) from (select *,row_number() over(partition by Symbol,end_date order by visible desc,update_flag desc) rn from fina_source where visible<=?) where rn=1),i as (select * exclude(rn) from (select *,row_number() over(partition by Symbol,end_date order by visible desc,update_flag desc) rn from income_source where visible<=?) where rn=1),c as (select * exclude(rn) from (select *,row_number() over(partition by Symbol,end_date order by visible desc,update_flag desc) rn from cash_source where visible<=?) where rn=1),j as (select f.Symbol,f.end_date,f.tr_yoy,f.netprofit_yoy,f.dt_netprofit_yoy,f.roe_waa,i.n_income_attr_p,c.n_cashflow_act,c.c_pay_acq_const_fiolta from f join i using(Symbol,end_date) join c using(Symbol,end_date)) select * from j qualify row_number() over(partition by Symbol order by end_date desc)=1""",[day,day,day]).df()
def members_at(m,day):return m[(m.in_date<=day)&(m.out_date.isna()|(m.out_date>=day))&m.ts_code.str.endswith((".SH",".SZ"))&~m.name.astype(str).str.contains("ST",case=False)].sort_values(["Symbol","in_date"]).drop_duplicates("Symbol",keep="last")
def run(raw,members_path,reports_dir,benchmark_path,start,end,out_path):
 m=pd.read_csv(members_path,dtype=str);m["Symbol"]=m.ts_code.str[:6];m["in_date"]=pd.to_datetime(m.in_date,errors="coerce");m["out_date"]=pd.to_datetime(m.out_date,errors="coerce")
 cfg=Config();con=connect(cfg,read_only=True)
 try:
  built=load_or_build_panel(cfg,"2016-01-01",end,con=con);p=repair_point_in_time_size(built.df);p.TradingDay=pd.to_datetime(p.TradingDay);p=p.sort_values(["Symbol","TradingDay"]).reset_index(drop=True);g=p.groupby("Symbol",sort=False);p["ret20"]=p.adj_close/g.adj_close.shift(20)-1;p["ma20_ratio"]=p.adj_close/g.adj_close.transform(lambda s:s.rolling(20,min_periods=20).mean())-1;adv=p.groupby("TradingDay").adv20.rank(pct=True,method="first");p["practical"]=(~p.is_st.fillna(True))&(~p.suspended.fillna(True))&(p.age>=252)&(p.Close>=5)&(p.Volume>0)&p.CircMV.notna()&(adv>.5);sessions=sorted(p.TradingDay.drop_duplicates());weeks=[d for d in weekly_last_sessions(sessions) if pd.Timestamp(start)<=d<=pd.Timestamp(end)];con.register("decision_dates",pd.DataFrame({"TradingDay":[d.date() for d in weeks]}));vals=con.execute("select f.TradingDay,f.Symbol,f.PETTM,f.PB from FundamentalData f join decision_dates d using(TradingDay)").df();con.register("fina_source",statement(str(Path(raw)/"fina_indicator_vip.csv"),["tr_yoy","netprofit_yoy","dt_netprofit_yoy","roe_waa"]));con.register("income_source",statement(str(Path(raw)/"income_vip.csv"),["n_income_attr_p"]));con.register("cash_source",statement(str(Path(raw)/"cashflow_vip.csv"),["n_cashflow_act","c_pay_acq_const_fiolta"]));reports=load_reports(reports_dir);etf=pd.read_csv(benchmark_path);etf=etf[etf.asset=="equity"].copy();etf.trade_date=pd.to_datetime(etf.trade_date,format="mixed");etf=etf.sort_values("trade_date");etf["ret20"]=etf.adj_close/etf.adj_close.shift(20)-1;bench=etf.set_index("trade_date").ret20;rows=[]
  for day in weeks:
   mem=members_at(m,day).rename(columns={"l1_name":"study_industry","name":"member_name"});base=p[(p.TradingDay==day)&p.Symbol.isin(mem.Symbol)].merge(mem[["Symbol","study_industry","member_name"]],on="Symbol",how="inner");base["industry"]=base.study_industry;base=base.merge(vals[vals.TradingDay==day][["Symbol","PETTM","PB"]],on="Symbol",how="left");counts=mem.groupby("study_industry").size();tradable=base[base.practical].copy();fin=tradable.merge(financial_snapshot(con,day.date()),on="Symbol",how="left");revision=tradable[["Symbol","industry"]].merge(consensus_revisions(reports,day)[["Symbol","revision"]],on="Symbol",how="left")
   for industry in sorted(mem.study_industry.dropna().unique()):
    b=tradable[tradable.industry==industry];f=fin[fin.industry==industry].copy();r=revision[revision.industry==industry].revision.dropna();n=int(counts.get(industry,0));fields=["tr_yoy","netprofit_yoy","dt_netprofit_yoy","roe_waa","n_income_attr_p","n_cashflow_act","c_pay_acq_const_fiolta"]
    for field in fields:f[field]=pd.to_numeric(f[field],errors="coerce")
    valid=f.dropna(subset=fields);market_coverage=len(base[base.industry==industry])/n if n else 0;financial_coverage=len(valid)/len(b) if len(b) else 0;analyst_coverage=len(r)/len(b) if len(b) else 0;triple=float(((valid.tr_yoy>0)&(valid.netprofit_yoy>0)&(valid.dt_netprofit_yoy>0)&(valid.n_income_attr_p>0)).mean()) if len(valid) else np.nan;concentration=float(b.nlargest(5,"CircMV").CircMV.sum()/b.CircMV.sum()) if b.CircMV.sum()>0 else np.nan;rows.append({"decision_date":day,"industry":industry,"member_count":n,"tradable_count":len(b),"market_coverage":market_coverage,"financial_coverage":0.0 if industry in UNSUPPORTED else financial_coverage,"analyst_coverage":analyst_coverage,"triple_growth_breadth":triple,"roe_median":float(valid.roe_waa.median()) if len(valid) else np.nan,"ocf_positive_breadth":float((valid.n_cashflow_act>0).mean()) if len(valid) else np.nan,"fcf_positive_breadth":float(((valid.n_cashflow_act-valid.c_pay_acq_const_fiolta)>0).mean()) if len(valid) else np.nan,"pe_median":float(b.loc[b.PETTM>0,"PETTM"].median()),"pb_median":float(b.loc[b.PB>0,"PB"].median()),"liquid_coverage":len(b)/n if n else 0,"diversification":1-concentration if pd.notna(concentration) else np.nan,"positive_revision_breadth":float((r>0).mean()) if len(r) else np.nan,"median_revision":float(r.median()) if len(r) else np.nan,"ma20_breadth":float((b.ma20_ratio>0).mean()) if len(b) else np.nan,"relative20":float(b.ret20.mean()-bench.get(day,np.nan)),"top_symbols":json.dumps(b.nlargest(20,"adv20").Symbol.tolist(),ensure_ascii=False)})
  raw_states=pd.DataFrame(rows);scored=score_weekly_states(raw_states);marked=mark_entry_events(scored,sessions);marked.to_csv(out_path,index=False,date_format="%Y-%m-%d");return {"panel_version":built.version_hash,"weeks":len(weeks),"industries":marked.industry.nunique(),"rows":len(marked),"events":int(marked.entry_event.sum()),"output":out_path}
 finally:con.close()
def main(argv=None):
 p=argparse.ArgumentParser();p.add_argument("--raw",default="overall/a-share-quarterly-statements-raw");p.add_argument("--members",default="overall/a-share-sw2021-members.csv");p.add_argument("--reports",default="overall/a-share-report-rc-raw");p.add_argument("--benchmark",default="overall/a-share-equity-etf-daily-current.csv");p.add_argument("--start",default="2017-01-06");p.add_argument("--end",default="2025-12-31");p.add_argument("--out",default="overall/a-share-weekly-industry-states.csv");a=p.parse_args(argv);print(json.dumps(run(a.raw,a.members,a.reports,a.benchmark,a.start,a.end,a.out),ensure_ascii=False,indent=2));return 0
if __name__=="__main__":raise SystemExit(main())
